using System.Numerics;
using System.Runtime.CollectionsMarshal;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _productsByCategory = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, double price)
    {
        _categories[code] = category;
        _prices[code] = price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_productsByCategory, category, out bool exists);
        if (!exists)
            list = new List<string>();
        list!.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    /// <summary>
    /// Computes total price for a batch of codes using SIMD-accelerated summation.
    /// </summary>
    public double GetTotalPrice(IReadOnlyList<string> codes)
    {
        int count = codes.Count;
        if (count == 0)
            return 0d;

        // Resolve prices into a contiguous buffer for vectorized summation
        Span<double> prices = count <= 256
            ? stackalloc double[count]
            : new double[count];

        int resolved = 0;
        for (int i = 0; i < count; i++)
        {
            if (_prices.TryGetValue(codes[i], out var price))
                prices[resolved++] = price;
        }

        return SimdSum(prices[..resolved]);
    }

    /// <summary>
    /// Overload accepting any enumerable (non-SIMD path for streaming scenarios).
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        double total = 0d;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    /// <summary>
    /// O(1) category lookup using reverse index instead of O(n) linear scan.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_productsByCategory.TryGetValue(category, out var products))
            return new List<string>(products);
        return new List<string>();
    }

    /// <summary>
    /// SIMD-accelerated double summation using hardware vectors.
    /// </summary>
    private static double SimdSum(ReadOnlySpan<double> values)
    {
        double sum = 0d;
        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<double>.Count)
        {
            var vSum = Vector<double>.Zero;
            int vectorEnd = values.Length - values.Length % Vector<double>.Count;

            ReadOnlySpan<Vector<double>> vectors = MemoryMarshal.Cast<double, Vector<double>>(values[..vectorEnd]);
            for (int v = 0; v < vectors.Length; v++)
                vSum += vectors[v];

            sum = Vector.Sum(vSum);
            i = vectorEnd;
        }

        // Scalar tail
        for (; i < values.Length; i++)
            sum += values[i];

        return sum;
    }
}

